	@Test
	void xsdStringSettingIsObservedForEachLiteral() throws IOException {
		assertOutput("<urn:s> <urn:p> \"first\" <urn:g> .\n"
				+ "<urn:s> <urn:p> \"second\"^^<http://www.w3.org/2001/XMLSchema#string> <urn:g> .\n"
				+ "<urn:s> <urn:p> \"third\" <urn:g> .\n", writer -> {
					writer.startRDF();
					writer.handleStatement(statement(VF.createLiteral("first", XSD.STRING)));
					writer.getWriterConfig().set(BasicWriterSettings.XSD_STRING_TO_PLAIN_LITERAL, false);
					writer.handleStatement(statement(VF.createLiteral("second", XSD.STRING)));
					writer.getWriterConfig().set(BasicWriterSettings.XSD_STRING_TO_PLAIN_LITERAL, true);
					writer.handleStatement(statement(VF.createLiteral("third", XSD.STRING)));
					writer.endRDF();
				});
	}

